#!/bin/bash

# ws models
#
#   command arg:  <version>, the orc ws version the app expects
#   prints:       a whole Go file with the types the ws snippets use
#   settings:     WS_PACKAGE    default main
#                 WS_CONN_TYPE  default WsConn
#
#   Write it to its own file, so its imports stay separate from the app's:
#       ${ORC_WS}/models.sh 0.1.0 | gofmt > ws_models.go || exit 1

: "${WS_PACKAGE:=main}"
: "${WS_CONN_TYPE:=WsConn}"
. "$(dirname "${BASH_SOURCE[0]}")/version.sh" "${1}"

cat << EOF
// Code generated by orc ws ${ORC_WS_V} (models.sh). DO NOT EDIT.

package ${WS_PACKAGE}

import (
	"bufio"
	"net"
)

// ${WS_CONN_TYPE} is an upgraded websocket connection. Write frames to Conn.
// Read frames through Reader: it's the buffer the handshake request was read
// with, so it may already hold the first frames.
type ${WS_CONN_TYPE} struct {
	Conn   net.Conn
	Reader *bufio.Reader
}
EOF
